import React, { useState } from 'react';
import { 
  Trash2, Map, Calendar, Star, LineChart, Users, 
  HardHat, FileText, Activity, ShieldAlert, ChevronLeft, 
  Database, Radio, Box
} from 'lucide-react';

const Dashboard = () => {
  const [currentView, setCurrentView] = useState('MENU');

  const allTabs = [
    { id: 'BINS', label: '01_BIN_MONITORING', icon: <Trash2 size={24}/> },
    { id: 'ZONES', label: '02_AREAS_&_ZONES', icon: <Map size={24}/> },
    { id: 'SCHEDULE', label: '03_COLL_SCHEDULE', icon: <Calendar size={24}/> },
    { id: 'POINTS', label: '04_REWARDS_POINTS', icon: <Star size={24}/> },
    { id: 'ANALYTICS', label: '05_SYS_ANALYTICS', icon: <LineChart size={24}/> },
    { id: 'CITIZENS', label: '06_CITIZEN_INFO', icon: <Users size={24}/> },
    { id: 'WORKERS', label: '07_WORKER_NODES', icon: <HardHat size={24}/> },
    { id: 'REPORTS', label: '08_SYS_REPORTS', icon: <FileText size={24}/> },
  ];

  // --- COMPONENT: BIN MONITORING CONTENT ---
  // This is a placeholder for actual content to show how the size adapts
  const BinContent = () => (
    <div className="grid grid-cols-1 md:grid-cols-3 gap-6 w-full animate-slot">
      {[1, 2, 3, 4, 5, 6].map((i) => (
        <div key={i} className="bg-[#FDFAD8] border-4 border-[#47510B] p-6 rounded-2xl shadow-[6px_6px_0_0_#47510B]">
          <div className="flex justify-between items-start mb-4">
            <Box className="text-[#AB1717]" />
            <span className="text-[10px] font-black bg-[#CAD23C] px-2 py-1 rounded border-2 border-[#47510B]">SEC_{i}04</span>
          </div>
          <h4 className="font-black text-[#47510B] text-lg uppercase">Bin_Unit_0{i}</h4>
          <div className="w-full bg-[#A1AED1] h-3 rounded-full mt-4 border-2 border-[#47510B] overflow-hidden">
            <div className="bg-[#AB1717] h-full" style={{ width: `${Math.random() * 100}%` }} />
          </div>
          <p className="text-[9px] font-bold mt-2 opacity-60 italic">CAPACITY_READING_LIVE</p>
        </div>
      ))}
    </div>
  );

  return (
    <div className="w-full min-h-screen bg-[#FDFAD8] p-4 md:p-10 flex flex-col items-center font-sans overflow-y-auto">

      {/* THE MAIN CONTAINER - Uses flex-col but allowed to grow */}
      <div className="w-full max-w-[1200px] flex flex-col gap-6">

        {/* HEADER: Always compact and stuck to the top */}
        <div className="bg-[#AB1717] border-[6px] border-[#47510B] rounded-t-[40px] rounded-b-[15px] p-6 md:px-10 md:py-8 shadow-[8px_8px_0_0_#47510B] shrink-0">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-5">
              <div className="bg-[#FDFAD8] p-2 rounded-xl border-4 border-[#47510B] shadow-[4px_4px_0_0_#47510B]">
                <ShieldAlert size={28} className="text-[#AB1717]" />
              </div>
              <div>
                <p className="text-[9px] font-black uppercase tracking-[0.4em] text-[#FDFAD8] opacity-50 mb-1">Terminal.System.v3</p>
                <h1 className="text-2xl md:text-4xl font-black italic text-[#FDFAD8] uppercase tracking-tighter leading-none">
                  TRASH<span className="text-[#CAD23C]">2</span>TRACK
                </h1>
              </div>
            </div>
            <Activity className="text-[#CAD23C] animate-pulse hidden sm:block" size={32} />
          </div>
        </div>

        {/* CONTENT CHASSIS: This box will grow vertically to fit all contents */}
        <div className="bg-[#A1AED1] border-[6px] border-[#47510B] rounded-[35px] p-6 md:p-10 shadow-[12px_12px_0_0_#47510B] min-h-[400px] relative transition-all duration-500">

          {currentView === 'MENU' ? (
            <div className="animate-slot">
              <div className="flex items-center gap-2 mb-8 border-b-4 border-[#47510B]/10 pb-4">
                <Radio size={16} className="text-[#AB1717] animate-pulse" />
                <h3 className="text-[10px] font-black uppercase tracking-[0.4em] text-[#47510B]">Select_Operational_Matrix</h3>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 md:gap-6">
                {allTabs.map((tab) => (
                  <button
                    key={tab.id}
                    onClick={() => setCurrentView(tab.id)}
                    className="group relative flex flex-col items-center justify-center gap-3 p-6 rounded-[24px] border-[5px] border-[#47510B] bg-[#FDFAD8] transition-all hover:-translate-y-1 hover:bg-[#CAD23C] shadow-[0_8px_0_0_#47510B] active:shadow-none active:translate-y-1"
                  >
                    <div className="text-[#AB1717] group-hover:text-[#47510B] transition-transform">{tab.icon}</div>
                    <span className="text-[9px] font-black uppercase text-[#47510B] text-center leading-tight">
                      {tab.label.split('_').slice(1).join(' ')}
                    </span>
                  </button>
                ))}
              </div>
            </div>
          ) : (
            /* DYNAMIC TAB VIEW: This is where the contents live */
            <div className="animate-slot flex flex-col gap-8">
              <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 border-b-4 border-[#47510B]/20 pb-6">
                <button 
                  onClick={() => setCurrentView('MENU')}
                  className="flex items-center gap-2 bg-[#47510B] text-[#FDFAD8] px-4 py-2 rounded-xl font-black uppercase text-[10px] w-fit hover:bg-[#AB1717] transition-all"
                >
                  <ChevronLeft size={16} /> Return_To_Main
                </button>
                <div className="flex items-center gap-3">
                  <Database size={20} className="text-[#47510B]" />
                  <h2 className="text-2xl md:text-3xl font-black italic text-[#47510B] uppercase tracking-tighter">
                    {currentView} <span className="text-[#AB1717]">_LIVE_FEED</span>
                  </h2>
                </div>
              </div>

              {/* CONTENTS GO HERE: The parent container will stretch to fit these */}
              <div className="w-full">
                {currentView === 'BINS' ? <BinContent /> : (
                  <div className="flex flex-col items-center justify-center py-20 opacity-30 italic text-[#47510B]">
                    <Radio size={48} className="mb-4 animate-ping" />
                    <p className="font-black uppercase tracking-widest text-center">Module_Data_Not_Yet_Synched</p>
                    <p className="text-[10px] mt-2 font-bold">Awaiting_Uplink_Signal_For: {currentView}</p>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>

        {/* SYSTEM STATUS FOOTER */}
        <div className="flex justify-center items-center py-6 opacity-40">
            <p className="text-[9px] font-black uppercase tracking-[1em] text-[#47510B]">
              Secure.Terminal.Build_2026.03
            </p>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
